package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GroupProductLinksTest {
 @Test public void everyGroupingSharingLinkPreservesObjectsAndNoDivisionNotation(){Checker checker=new Checker();Set<String> seen=new HashSet<>();int count=0;for(int unit:new int[]{1,2,5,10})for(int n=1;n<=10;n++){if(unit*n>50)continue;for(int mode=0;mode<2;mode++){count++;Question q=GroupProductLinks.make(unit,n,mode);assertTrue(seen.add(q.signature()));assertFalse(q.prompt.contains("÷"));assertEquals("groupProductObjects",q.diagram.type);assertEquals(unit*n,q.diagram.values[0],0);q.answers=new String[]{"poison"};q.expression="poison";assertTrue(checker.check(q,List.of(),List.of(""+n)).correct());assertEquals(Checker.Status.WRONG_ANSWER,checker.check(q,List.of(),List.of(""+(n+1))).status);HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(n+(mode==0?5:4),h.size());assertTrue(h.step(0).accepts(""+(unit*n)));assertTrue(h.step(1).accepts(""+unit));for(int j=1;j<=n;j++)assertTrue(h.step(j+1).accepts(""+(unit*(n-j))));assertTrue(h.step(n+2).accepts(""+n));if(mode==0)assertTrue(h.step(n+3).accepts("0"));assertTrue(h.step(h.size()-1).accepts(""+n));for(int j=0;j<h.size();j++)assertFalse(h.step(j).instruction.contains("÷"));}}
 assertEquals(70,count);assertEquals(count,GroupProductLinks.DOMAIN.size());for(String invalid:List.of("물건 11개를 2개씩 묶어요.\n2 × □ = 11","물건 10개를 2명이 똑같이 나눠요.\n5 × □ = 10","물건 60개를 10개씩 묶어요.\n10 × □ = 60"))assertNull(GroupProductLinks.read(new Question(GroupProductLinks.ID,invalid,"","0")));
 }
 @Test public void completeFreshSupplyInGradeTwoOnly(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(GroupProductLinks.ID,2));assertFalse(pack.inGrade(GroupProductLinks.ID,1));assertFalse(pack.inGrade(GroupProductLinks.ID,3));assertFalse(Curriculum.inCurriculum(GroupProductLinks.SKILL,2022));Generator g=new Generator(new Random(208));List<String> recent=new ArrayList<>();CurriculumLimits limits=GlobalCurriculum.limits(pack.id,GroupProductLinks.ID,2);for(int i=0;i<70;i++){Question q=g.next(GroupProductLinks.ID,recent,false,limits);assertTrue(limits.allows(q));assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertNotNull(GroupProductLinks.read(q));}}
}
